    [TestMethod]
    [DataRow(10.5, "$", "$10.50")]
    [DataRow(1234.567, "$", "$1234.57")]
    [DataRow(0.0, "€", "€0.00")]
    [DataRow(-5.1, "$", "$-5.10")]
    public void FormatCurrency_VariousAmounts_ReturnsExpectedFormat(
        double amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency((decimal)amount, symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(99.99m);

        Assert.StartsWith("$", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(50m, "£");

        Assert.StartsWith("£", result);
    }

    [TestMethod]
    public void FormatCurrency_AlwaysTwoDecimalPlaces_MatchesPattern()
    {
        var result = _formatter.FormatCurrency(7m);

        Assert.MatchesRegex(@"\.\d{2}$", result);
    }

    [TestMethod]
    public void FormatCurrency_WholeNumber_EndsWithTwoZeros()
    {
        var result = _formatter.FormatCurrency(42m);

        Assert.EndsWith(".00", result);
    }
}

